import test from 'node:test';import assert from 'node:assert/strict';import {mkdtempSync,writeFileSync,readFileSync,rmSync} from 'node:fs';import {tmpdir} from 'node:os';import {join,resolve,sep} from 'node:path';import {spawnSync} from 'node:child_process';import {savedRehearsalGuideFixtures} from './helpers/workspace-fixtures.js';import {prepareWalletSavedSourceBundle,reviewWalletSavedBundle,encodeWalletSavedBundleReview,reviewWalletSavedBundleReceipt,encodeWalletSavedBundleReceiptCheck} from '../src/file-read-status.js';
test('offline saved receipt checks reproduce API output and distinguish faithful failure from altered claims',async()=>{
 const folder=mkdtempSync(join(tmpdir(),'threecore-bundle-receipt-')),bundlePath=join(folder,'bundle.json'),receiptPath=join(folder,'receipt.json'),text=savedRehearsalGuideFixtures()[0].text,bundle=await prepareWalletSavedSourceBundle(text,text),run=(args,exit)=>{const result=spawnSync(process.execPath,['scripts/wallet-saved-bundle.js',...args],{encoding:'utf8',windowsHide:true,timeout:30000});assert.equal(result.error,undefined);assert.equal(result.status,exit,result.stderr);return result;};
 try{writeFileSync(bundlePath,bundle.text);const expected=await reviewWalletSavedBundle(bundle.text),saved=encodeWalletSavedBundleReview(expected);writeFileSync(receiptPath,saved);assert.equal(run(['verify-receipt',bundlePath,receiptPath,'--json'],0).stdout,encodeWalletSavedBundleReceiptCheck(await reviewWalletSavedBundleReceipt(expected,saved)));const changed=JSON.parse(saved);changed.authenticated=true;writeFileSync(receiptPath,JSON.stringify(changed));assert.equal(JSON.parse(run(['verify-receipt',bundlePath,receiptPath,'--json'],2).stdout).matchesRecomputation,false);assert.equal(readFileSync(bundlePath,'utf8'),bundle.text);
  const broken=JSON.parse(bundle.text),comparison=JSON.parse(broken.comparisonText);comparison.authenticated=true;broken.comparisonText=JSON.stringify(comparison);const brokenText=JSON.stringify(broken),negative=encodeWalletSavedBundleReview(await reviewWalletSavedBundle(brokenText));writeFileSync(bundlePath,brokenText);writeFileSync(receiptPath,negative);const faithful=JSON.parse(run(['verify-receipt',bundlePath,receiptPath,'--json'],0).stdout);assert(faithful.matchesRecomputation);assert.equal(faithful.expectedSourceFilesAvailable,false);assert.equal(run(['extract',bundlePath,'before'],2).stdout,'');assert.equal(run(['verify-receipt',bundlePath,receiptPath,'--unknown'],1).stdout,'');assert.equal(readFileSync(bundlePath,'utf8'),brokenText);assert.equal(readFileSync(receiptPath,'utf8'),negative);
 }finally{assert(resolve(folder).startsWith(resolve(tmpdir())+sep));rmSync(folder,{recursive:true,force:true});}
});
